-- 정부 기관 사이트 디렉터리 · CRM용 Supabase 스키마 + 시드
-- 실행: Supabase SQL Editor 에 통째로 붙여넣기 (재실행해도 안전 — upsert)
-- 참고: RLS 를 켜면 authenticated 롤에 GRANT 가 별도로 필요 (아래 포함)

create table if not exists public.agency_sites (
  id          integer primary key,
  name        text not null,
  org         text not null,
  description text not null default '',
  category    text not null,          -- 정책자금·정부지원금·R&D·투자·바우처·창업·고용·수출·판로·기업인증·IP·조달·교육·지자체·지역사업
  region      text not null default '전국',  -- 전국 | 17개 시·도
  type        text not null,          -- 정부부처·공공기관·지자체·진흥원·재단·협회·금융
  tags        text[] not null default '{}',
  url         text not null,
  sort_order  integer not null default 0,
  is_active   boolean not null default true,
  updated_at  timestamptz not null default now()
);
create index if not exists agency_sites_category_idx on public.agency_sites (category);
create index if not exists agency_sites_region_idx   on public.agency_sites (region);
create index if not exists agency_sites_tags_gin     on public.agency_sites using gin (tags);

-- 사용자별 즐겨찾기 (auth.users 기준)
create table if not exists public.agency_site_favorites (
  user_id    uuid not null references auth.users(id) on delete cascade,
  site_id    integer not null references public.agency_sites(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, site_id)
);

alter table public.agency_sites enable row level security;
alter table public.agency_site_favorites enable row level security;
drop policy if exists "agency_sites read for authenticated" on public.agency_sites;
create policy "agency_sites read for authenticated" on public.agency_sites for select to authenticated using (true);
drop policy if exists "favorites own rows" on public.agency_site_favorites;
create policy "favorites own rows" on public.agency_site_favorites for all to authenticated using (auth.uid() = user_id) with check (auth.uid() = user_id);
grant select on public.agency_sites to authenticated;
grant select, insert, delete on public.agency_site_favorites to authenticated;

on conflict (id) do update set
  name = excluded.name, org = excluded.org, description = excluded.description,
  category = excluded.category, region = excluded.region, type = excluded.type,
  tags = excluded.tags, url = excluded.url, sort_order = excluded.sort_order, updated_at = now();
